def pad(message):
    # Your code here
    x=message
    if len(x)%2==1:
        while len(x)<140:
            if len(x)==139:
                x=x+'l'
            else:
                x=x+'l'
                x=x+'o'
    elif len(x)%2==0 and x!=140:
        x=x+' '
        while len(x)<140:
            if len(x)==139:
                x=x+'l'
            else:
                x=x+'l'
                x=x+'o'


    return x
```

